// 1. Ambil semua data dari Supabase
const allData = $input.all();

// 2. Ambil 50 data paling akhir (terbaru)
const recentData = allData.slice(-50).reverse();

// 3. Siapkan variabel counter untuk membantu Gemini menghitung secara absolut
let tokohCounts = { "Khamenei": 0, "Trump": 0, "Netanyahu": 0 };
let sentimenCounts = { "MARAH": 0, "PASRAH": 0, "SETUJU": 0 };

const mappingKoreksi = {
    'iran': 'Khamenei',
    'israel': 'Netanyahu',
    'zionis': 'Netanyahu'
};
const allowedNames = ['Khamenei', 'Trump', 'Netanyahu'];

// 4. Proses pemecahan koma (explode) dan rekap data
const dbData = recentData.map(item => {
    let komentar = item.json.komentar || "";
    let kategori = (item.json.kategori || "PASRAH").toUpperCase();
    let tokohRaw = item.json.tokoh_terkait || "";

    if (sentimenCounts[kategori] !== undefined) {
        sentimenCounts[kategori]++;
    }

    let cleanedTokohList = [];
    if (tokohRaw && typeof tokohRaw === 'string') {
        // PECAH BERDASARKAN KOMA DAN BERSIHKAN SPASI
        let parts = tokohRaw.split(',').map(t => t.trim());

        parts.forEach(p => {
            let lowerP = p.toLowerCase();
            // Jalankan mapping koreksi halusinasi
            let mapped = mappingKoreksi[lowerP] || p;

            // Validasi apakah termasuk 3 tokoh utama
            let matched = allowedNames.find(a => a.toLowerCase() === mapped.toLowerCase());
            if (matched) {
                cleanedTokohList.push(matched);
                tokohCounts[matched]++; // Hitung++ per nama individu
            }
        });
    }

    let tokohFinal = cleanedTokohList.length > 0 ? cleanedTokohList.join(", ") : "Tidak ada";
    return `Teks: "${komentar}", Sentimen: ${kategori}, Tokoh: ${tokohFinal}`;
});

// 5. Buat teks ringkasan statistik mutlak untuk disuapkan ke Gemini (TYPO SUDAH DIPERBAIKI DI SINI)
let ringkasanStatistik = `[STATISTIK UTAMA 50 DATA TERBARU] Total Sebutan Tokoh riil setelah dibersihkan -> Khamenei: ${tokohCounts["Khamenei"]} kali, Trump: ${tokohCounts["Trump"]} kali, Netanyahu: ${tokohCounts["Netanyahu"]} kali. Distribusi Sentimen -> Marah: ${sentimenCounts["MARAH"]}, Pasrah: ${sentimenCounts["PASRAH"]}, Setuju: ${sentimenCounts["SETUJU"]}.`;

// 6. Tarik pesan user dari Webhook
let userMessage = "Halo";
try {
    userMessage = $('Webhook').item.json.body?.pesan || "Halo";
} catch (error) {
    userMessage = "Halo"; 
}

return {
  json: {
    pertanyaan: userMessage,
    data_konteks: ringkasanStatistik + " | DETAIL DATA MENTAH: " + dbData.join(" | ")
  }
};
